CREATE TABLE `conversations` (`id` CHAR(36) NOT NULL,`type` ENUM('CUSTOMER_MERCHANT','SUPPORT') NOT NULL,`status` ENUM('OPEN','CLOSED') NOT NULL DEFAULT 'OPEN',`open_key` VARCHAR(255) NULL,`subject` VARCHAR(255) NOT NULL,`closed_by_user_id` CHAR(36) NULL,`closed_at` DATETIME(3) NULL,`last_message_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,UNIQUE INDEX `conversations_open_key_key`(`open_key`),INDEX `conversations_status_idx`(`status`),INDEX `conversations_type_idx`(`type`),INDEX `conversations_last_message_at_idx`(`last_message_at`),INDEX `conversations_created_at_idx`(`created_at`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `conversation_participants` (`conversation_id` CHAR(36) NOT NULL,`user_id` CHAR(36) NOT NULL,`role_snapshot` VARCHAR(50) NOT NULL,`joined_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`left_at` DATETIME(3) NULL,INDEX `conversation_participants_user_id_conversation_id_idx`(`user_id`,`conversation_id`),PRIMARY KEY (`conversation_id`,`user_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `conversation_contexts` (`conversation_id` CHAR(36) NOT NULL,`store_id` CHAR(36) NULL,`product_id` CHAR(36) NULL,`commerce_order_id` CHAR(36) NULL,`tourism_booking_id` CHAR(36) NULL,`live_in_booking_id` CHAR(36) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,INDEX `conversation_contexts_store_id_idx`(`store_id`),INDEX `conversation_contexts_product_id_idx`(`product_id`),INDEX `conversation_contexts_commerce_order_id_idx`(`commerce_order_id`),INDEX `conversation_contexts_tourism_booking_id_idx`(`tourism_booking_id`),INDEX `conversation_contexts_live_in_booking_id_idx`(`live_in_booking_id`),PRIMARY KEY (`conversation_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `messages` (`id` CHAR(36) NOT NULL,`conversation_id` CHAR(36) NOT NULL,`sender_user_id` CHAR(36) NOT NULL,`message` TEXT NOT NULL,`attachment_url` VARCHAR(1000) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `messages_conversation_id_created_at_idx`(`conversation_id`,`created_at`),INDEX `messages_sender_user_id_idx`(`sender_user_id`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `message_reads` (`message_id` CHAR(36) NOT NULL,`user_id` CHAR(36) NOT NULL,`read_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `message_reads_user_id_read_at_idx`(`user_id`,`read_at`),PRIMARY KEY (`message_id`,`user_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `conversations` ADD CONSTRAINT `conversations_closed_by_user_id_fkey` FOREIGN KEY (`closed_by_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
