ALTER TABLE `conversation_contexts` ADD CONSTRAINT `conversation_contexts_conversation_id_fkey` FOREIGN KEY (`conversation_id`) REFERENCES `conversations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,ADD CONSTRAINT `conversation_contexts_store_id_fkey` FOREIGN KEY (`store_id`) REFERENCES `stores`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,ADD CONSTRAINT `conversation_contexts_product_id_fkey` FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,ADD CONSTRAINT `conversation_contexts_commerce_order_id_fkey` FOREIGN KEY (`commerce_order_id`) REFERENCES `commerce_orders`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,ADD CONSTRAINT `conversation_contexts_tourism_booking_id_fkey` FOREIGN KEY (`tourism_booking_id`) REFERENCES `tourism_bookings`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,ADD CONSTRAINT `conversation_contexts_live_in_booking_id_fkey` FOREIGN KEY (`live_in_booking_id`) REFERENCES `live_in_bookings`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `messages` ADD CONSTRAINT `messages_conversation_id_fkey` FOREIGN KEY (`conversation_id`) REFERENCES `conversations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,ADD CONSTRAINT `messages_sender_user_id_fkey` FOREIGN KEY (`sender_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
